// FUNCTION: BFME2 0x002E4573 size=103 name=?getCampaignDifficulty@OptionPreferences@@QAEHXZ evidence=N:ledger
Int OptionPreferences::getCampaignDifficulty()
{
	OptionPreferences::const_iterator entry = find("CampaignDifficulty");
	if (entry == end())
		return TheScriptEngine->m_globalDifficulty;
	Int difficulty = atoi(entry->second.str());
	if (difficulty < 0)
		difficulty = 0;
	if (difficulty > 2)
		difficulty = 2;
	return difficulty;
}

// FUNCTION: BFME2 0x002E45DA size=121 name=?getScrollFactor@OptionPreferences@@QAEMXZ evidence=N:ledger
float OptionPreferences::getScrollFactor(void)
{
	OptionPreferences::const_iterator entry = find("ScrollFactor");
	if (entry == end())
		return TheWritableGlobalData->m_keyboardDefaultScrollSpeedFactor;
	Int level = atoi(entry->second.str());
	if (level < 0)
		level = 1;
	if (level > 100)
		level = 100;
	return level * 0.02f;
}



