// FUNCTION: BFME2 0x002E4AA1 size=140 name=?getResolution@OptionPreferences@@QAEXPAH0@Z evidence=N:ledger
void OptionPreferences::getResolution(Int *xres, Int *yres)
{
	*xres = TheWritableGlobalData->m_xResolution;
	*yres = TheWritableGlobalData->m_yResolution;
	OptionPreferences::const_iterator entry = find("Resolution");
	if (entry == end())
		return;
	Int selectedXRes, selectedYRes;
	if (sscanf(entry->second.str(), "%d%d", &selectedXRes, &selectedYRes) != 2)
		return;
	*xres = selectedXRes;
	*yres = selectedYRes;
}



// FUNCTION: BFME2 0x002E4B2D size=154 name=?getVolume@OptionPreferences@@QAEMH@Z evidence=N:ledger
Real OptionPreferences::getVolume(Int index)
{
	if (index < 0 || index >= 5)
		return 0.0f;
	OptionPreferences::const_iterator entry = find(g_volumePreferenceKeys[index]);
	if (entry == end())
	{
		// nothing saved yet: the audio settings' default, as a percentage
		return TheAudio->getAudioSettings()->m_defaultVolumes[index] * 100.0f;
	}
	Real stored = (Real)atof(entry->second.str());
	if (stored < 0.0f)
		stored = 0.0f;
	return stored;
}

