// FUNCTION: BFME2 0x002E50BB size=143 name=?setLANIPAddress@OptionPreferences@@QAEXI@Z evidence=N:ledger
void OptionPreferences::setLANIPAddress(unsigned int ip)
{
	// Dotted-quad text of the packed address, stored under the LAN key.
	AsciiString dotted;
	dotted.format("%d.%d.%d.%d", ip >> 24, ((ip & 0xff0000) >> 16), ((ip & 0xff00) >> 8), (ip & 0xff));
	AsciiString lanKey("IPAddress");
	AsciiString &stored = (*this)[lanKey];
	stored = dotted;
}



