// FUNCTION: BFME2 0x002E54EA size=83 name=?rva002E54EA@OptionPreferences@@QAEXXZ evidence=?:placeholder
void OptionPreferences::eraseSettings()
{
	for (Int i = 0; i < 9; ++i)
		erase(BfmeEnumTable[i].m_key);
}

// FUNCTION: BFME2 0x002E553D size=155 name=?setSetting@OptionPreferences@@QAEXHH@Z evidence=N:ledger
void OptionPreferences::setSetting(Int setting, Int value)
{
	if (value < 0 || value >= BfmeEnumTable[setting].m_count)
	{
		erase(BfmeEnumTable[setting].m_key);
	}
	else
	{
		AsciiString key(BfmeEnumTable[setting].m_key);
		const char *name = BfmeEnumTable[setting].m_subtable[value];
		AsciiString &slot = (*this)[key];
		slot.set(name);
	}
}

